    def __init__(self, expression):
        self.expression = expression.replace(' ', '')
        self.current_index = 0
        self.current_char = self.expression[self.current_index] if self.expression else None

    def error(self):
        raise Exception("Invalid character or sequence")

    def advance(self):
        self.current_index += 1
        if self.current_index < len(self.expression):
            self.current_char = self.expression[self.current_index]
        else:
            self.current_char = None

    def parse_number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def parse_factor(self):
        if self.current_char == '(':
            self.advance()
            result = self.parse_expression()
            if self.current_char != ')':
                self.error()
            self.advance()
            return result
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.parse_number()

        self.error()

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            operation = self.current_char
            self.advance()
            if operation == '*':
                result *= self.parse_factor()
            elif operation == '/':
                divisor = self.parse_factor()
                if divisor == 0:
                    self.error()
                result /= divisor
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            operation = self.current_char
            self.advance()
            if operation == '+':
                result += self.parse_term()
            elif operation == '-':
                result -= self.parse_term()
        return result

