class Evaluator:
    def __init__(self, expression):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def error(self):
        raise Exception("Invalid character in expression")

    def advance(self):
        """Advance the 'position' pointer and update 'current_char'."""
        self.position += 1
        self.current_char = self.expression[self.position] if self.position < len(self.expression) else None

    def skip_whitespace(self):
        """Skip whitespace characters in the expression."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        """Parse a number (integer or float) from the expression."""
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def parse_expression(self):
        """Parse and evaluate an expression with operator precedence."""
        values = []
        operators = []
        self.skip_whitespace()
        self.parse_term(values, operators)

        while self.current_char is not None:
            if self.current_char in '+-':
                operators.append(self.current_char)
                self.advance()
                self.parse_term(values, operators)
            else:
                break

        while operators:
            right = values.pop()
            left = values.pop()
            op = operators.pop()
            values.append(self.apply_operator(left, right, op))

        return values[0]

    def parse_term(self, values, operators):
        """Parse a term (factors) in the expression with higher precedence."""
        self.skip_whitespace()
        values.append(self.parse_factor())

        while self.current_char is not None and self.current_char in '*/':
            operators.append(self.current_char)
            self.advance()
            values.append(self.parse_factor())

    def parse_factor(self):
        """Parse a factor which can be a number or an expression in parentheses."""
        self.skip_whitespace()
        if self.current_char == '(':
            self.advance()
            result = self.parse_expression()
            self.advance()  # Skip the closing ')'
            return result
        return self.number()

    def apply_operator(self, left, right, operator):
        """Apply an operator to two values."""
        if operator == '+':
            return left + right
        elif operator == '-':
            return left - right
        elif operator == '*':
            return left * right
        elif operator == '/':
            return left / right
        else:
            self.error()

