class Evaluator:
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position]

    def error(self):
        raise Exception('Invalid syntax')

    def advance(self):
        self.position += 1
        if self.position >= len(self.expression):
            self.current_char = None
        else:
            self.current_char = self.expression[self.position]

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def parse_number(self):
        number_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            number_str += self.current_char
            self.advance()
        return float(number_str)

    def parse_factor(self):
        if self.current_char == '(':
            self.advance()  # Skip '('
            result = self.parse_expression()
            if self.current_char == ')':
                self.advance()  # Skip ')'
                return result
            else:
                self.error()
        elif self.current_char.isdigit() or (self.current_char == '-' and self.peek().isdigit()):
            return self.parse_number()
        else:
            self.error()

    def peek(self):
        peek_position = self.position + 1
        if peek_position >= len(self.expression):
            return None
        return self.expression[peek_position]

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char in ('*', '/'):
            operation = self.current_char
            self.advance()  # Skip operator
            if operation == '*':
                result *= self.parse_factor()
            elif operation == '/':
                result /= self.parse_factor()
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char in ('+', '-'):
            operation = self.current_char
            self.advance()  # Skip operator
            if operation == '+':
                result += self.parse_term()
            elif operation == '-':
                result -= self.parse_term()
        return result

